import { useState, useCallback } from "react";
import { useDropzone } from "react-dropzone";
import { Typography, Paper, Box } from "@mui/material";

const Dropzone = ({ category, onDrop }) => {
  const [uploadedFiles, setUploadedFiles] = useState([]);

  const handleDrop = useCallback(
    (acceptedFiles) => {
      onDrop(category, acceptedFiles);
      setUploadedFiles(acceptedFiles.map((file) => file.name)); // Store file names
    },
    [category, onDrop]
  );

  const { getRootProps, getInputProps, isDragActive } = useDropzone({
    onDrop: handleDrop,
    accept: "image/*",
    multiple: true,
  });

  return (
    <Paper
      {...getRootProps()}
      sx={{
        p: 2,
        textAlign: "center",
        border: "2px dashed #aaa",
        cursor: "pointer",
        backgroundColor: isDragActive ? "#f0f0f0" : "white",
      }}
    >
      <input {...getInputProps()} />
      <Typography variant="subtitle1" sx={{ textTransform: "capitalize", fontWeight: "bold" }}>
        {category.replace("photo", " Photo")}
      </Typography>
      <Typography variant="body2" color="textSecondary">
        Drag & drop images here, or click to select files
      </Typography>

      {/* Show message if files are uploaded */}
      {uploadedFiles.length > 0 ? (
        <Box mt={2}>
          <Typography variant="body2" color="primary">
            Files uploaded:
          </Typography>
          {uploadedFiles.map((file, index) => (
            <Typography key={index} variant="body2">
              {file}
            </Typography>
          ))}
        </Box>
      ) : (
        <Typography variant="body2" color="error" mt={2}>
          No files uploaded yet
        </Typography>
      )}
    </Paper>
  );
};

export default Dropzone;
